const fs = require('node:fs');
const relevant = /open-software-tenders|open-software-tender|expiry-verification/i;
const record = /retir|supersed|publicat|release|expir/i;
for (const root of ['products/services', 'products/distribution']) {
  if (!fs.existsSync(root)) continue;
  for (const path of fs.readdirSync(root, {recursive: true}).sort()) {
    if (relevant.test(path) && record.test(path) && /\.(json|md)$/.test(path)) console.log(root + '/' + path);
  }
}
